import { randomUUID } from "node:crypto";
import { mkdir, readFile, writeFile, unlink } from "node:fs/promises";
import path from "node:path";

/*
 * Client uploads on the server volume (TASK-014, ADR-033): UPLOAD_DIR (Kamal volume `inzenirji-crm-uploads`
 * mounted at /data/uploads). Names are generated by us; the original name is kept only in the database.
 */

export const MAX_FILE_BYTES = 20 * 1024 * 1024;
const ALLOWED = /^(image\/(jpeg|png|gif|webp|svg\+xml|heic|heif)|application\/pdf|application\/zip|text\/plain|application\/msword|application\/vnd\.openxmlformats-officedocument\.(wordprocessingml\.document|spreadsheetml\.sheet|presentationml\.presentation)|application\/vnd\.ms-excel|application\/postscript|application\/illustrator)$/;

export function uploadDir(env: Record<string, string | undefined> = process.env) {
  return env.UPLOAD_DIR ?? path.join(process.cwd(), ".uploads");
}

export function checkUpload(f: { size: number; type: string; name: string }): string | null {
  if (!f.size) return "Datoteka je prazna.";
  if (f.size > MAX_FILE_BYTES) return `»${f.name}« je večja od 20 MB.`;
  if (!ALLOWED.test(f.type || "")) return `Vrsta datoteke »${f.name}« ni podprta (slike, PDF, Word, Excel, ZIP).`;
  return null;
}

export async function saveFile(projectId: string, data: Buffer, original: string, dir = uploadDir()) {
  const ext = (path.extname(original).toLowerCase().match(/^\.[a-z0-9]{1,6}$/) ?? [""])[0];
  const rel = path.join(projectId, `${randomUUID()}${ext}`);
  await mkdir(path.join(dir, projectId), { recursive: true });
  await writeFile(path.join(dir, rel), data, { flag: "wx" });
  return rel;
}

export async function readStored(rel: string, dir = uploadDir()) {
  const full = path.resolve(dir, rel);
  if (!full.startsWith(path.resolve(dir) + path.sep)) throw new Error("BAD_PATH");
  return readFile(full);
}

export async function removeStored(rel: string, dir = uploadDir()) {
  const full = path.resolve(dir, rel);
  if (!full.startsWith(path.resolve(dir) + path.sep)) return;
  await unlink(full).catch(() => {});
}
